describe('Tab Navigation URL Hash Update', () => {
  beforeEach(() => {
    cy.visit('/page-with-tabs');
  });

  it('should update URL hash when switching between tabs', () => {
    // Verify initial state
    cy.url().should('include', '#overview');
    cy.get('[data-testid="tab-overview"]').should('have.class', 'active');
    cy.get('[data-testid="tab-details"]').should('not.have.class', 'active');

    // Click on details tab
    cy.get('[data-testid="tab-details"]').click();

    // Verify URL hash updated
    cy.url().should('include', '#details');
    cy.get('[data-testid="tab-details"]').should('have.class', 'active');
    cy.get('[data-testid="tab-overview"]').should('not.have.class', 'active');

    // Click on overview tab
    cy.get('[data-testid="tab-overview"]').click();

    // Verify URL hash updated back
    cy.url().should('include', '#overview');
    cy.get('[data-testid="tab-overview"]').should('have.class', 'active');
    cy.get('[data-testid="tab-details"]').should('not.have.class', 'active');
  });

  it('should handle hash changes and maintain tab state on page reload', () => {
    // Navigate to details tab and verify hash
    cy.get('[data-testid="tab-details"]').click();
    cy.url().should('include', '#details');

    // Reload the page
    cy.reload();

    // Verify tab state is preserved after reload
    cy.get('[data-testid="tab-details"]').should('have.class', 'active');
    cy.url().should('include', '#details');

    // Verify content is visible
    cy.get('[data-testid="details-content"]').should('be.visible');

    // Navigate to overview tab and verify hash updates
    cy.get('[data-testid="tab-overview"]').click();
    cy.url().should('include', '#overview');
    cy.get('[data-testid="tab-overview"]').should('have.class', 'active');
  });
});
